#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n, m, k;
    cin >> n >> m >> k;

    long long ansX, ansY;

    if (k < n) {
        ansX = k + 1;
        ansY = 1;
    } else {
        k -= n;
        long long count = k / (m - 1);
        ansX = n - count;
        if (count % 2 == 0) {
            ansY = 2 + (k % (m - 1));
        } else {
            ansY = m - (k % (m - 1));
        }
    }

    cout << ansX << " " << ansY << "\n";

    return 0;
}

